#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>
#include <openssl/evp.h>

typedef unsigned __int128 u128;
typedef struct { uint64_t r0,r1,r2,s1,s2; } pkey;
typedef struct { uint64_t h0,h1,h2; } pacc;

static inline uint64_t ld64(const uint8_t*p){uint64_t v;memcpy(&v,p,8);return v;}

static void pkey_init(pkey*k,const uint8_t*key){
  uint64_t t0=ld64(key),t1=ld64(key+8);
  k->r0=t0&0xffc0fffffffULL;
  k->r1=((t0>>44)|(t1<<20))&0xfffffc0ffffULL;
  k->r2=(t1>>24)&0x00ffffffc0fULL;
  k->s1=k->r1*(5<<2); k->s2=k->r2*(5<<2);
}
/* donna-64: 44/44/42 limbs */
static inline void pmul(pacc*a,const pkey*k){
  uint64_t h0=a->h0,h1=a->h1,h2=a->h2,c;
  u128 d0,d1,d2;
  d0=(u128)h0*k->r0+(u128)h1*k->s2+(u128)h2*k->s1;
  d1=(u128)h0*k->r1+(u128)h1*k->r0+(u128)h2*k->s2;
  d2=(u128)h0*k->r2+(u128)h1*k->r1+(u128)h2*k->r0;
  const uint64_t m44=0xfffffffffffULL,m42=0x3ffffffffffULL;
  h0=(uint64_t)d0&m44; c=(uint64_t)(d0>>44);
  d1+=c; h1=(uint64_t)d1&m44; c=(uint64_t)(d1>>44);
  d2+=c; h2=(uint64_t)d2&m42; c=(uint64_t)(d2>>42);
  h0+=c*5; c=h0>>44; h0&=m44; h1+=c;
  a->h0=h0;a->h1=h1;a->h2=h2;
}
static void pblocks(pacc*a,const pkey*k,const uint8_t*m,size_t nb){
  const uint64_t m44=0xfffffffffffULL;
  for(size_t i=0;i<nb;i++,m+=16){
    uint64_t t0=ld64(m),t1=ld64(m+8);
    a->h0+=t0&m44; a->h1+=((t0>>44)|(t1<<20))&m44; a->h2+=((t1>>24)&0x3ffffffffffULL)|(1ULL<<40);
    pmul(a,k);
  }
}
/* key from accumulator-like value (r^n), used as multiplier */
static void key_from_acc(pkey*k,const pacc*a){
  k->r0=a->h0;k->r1=a->h1;k->r2=a->h2;k->s1=k->r1*20;k->s2=k->r2*20;
}
static void ppow(pacc*out,const pkey*k,uint64_t e){
  /* out = r^e */
  pacc res={1,0,0}; pacc b={k->r0,k->r1,k->r2};
  while(e){
    pkey bk; key_from_acc(&bk,&b);
    if(e&1) pmul(&res,&bk);
    e>>=1;
    if(e){ pacc t=b; pmul(&t,&bk); b=t; }
  }
  *out=res;
}

#define MAXT 32
typedef struct {
  const uint8_t*pt; uint8_t*ct; size_t off,len; /* byte range */
  const uint8_t*key; const uint8_t*nonce; pkey pk; pacc acc; int pad_last; int err;
} job;

static void*worker(void*arg){
  job*j=(job*)arg;
  uint8_t iv[16]; uint32_t ctr=(uint32_t)(1+j->off/64);
  memcpy(iv,&ctr,4); memcpy(iv+4,j->nonce,12);
  EVP_CIPHER_CTX*c=EVP_CIPHER_CTX_new();
  int ol; j->err=0;
  if(!c||!EVP_EncryptInit_ex(c,EVP_chacha20(),NULL,j->key,iv)){j->err=1;return NULL;}
  j->acc.h0=j->acc.h1=j->acc.h2=0;
  const size_t CH=16384;
  size_t done=0;
  while(done<j->len){
    size_t n=j->len-done; if(n>CH)n=CH;
    EVP_EncryptUpdate(c,j->ct+j->off+done,&ol,j->pt+j->off+done,(int)n);
    size_t nb=n/16;
    pblocks(&j->acc,&j->pk,j->ct+j->off+done,nb);
    size_t rem=n-nb*16;
    if(rem){ uint8_t b[16]={0}; memcpy(b,j->ct+j->off+done+nb*16,rem); pblocks(&j->acc,&j->pk,b,1);}
    done+=n;
  }
  EVP_CIPHER_CTX_free(c);
  return NULL;
}

static void addacc(pacc*a,const pacc*b){
  const uint64_t m44=0xfffffffffffULL,m42=0x3ffffffffffULL; uint64_t c;
  a->h0+=b->h0; a->h1+=b->h1; a->h2+=b->h2;
  c=a->h0>>44;a->h0&=m44;a->h1+=c; c=a->h1>>44;a->h1&=m44;a->h2+=c;
  c=a->h2>>42;a->h2&=m42;a->h0+=c*5; c=a->h0>>44;a->h0&=m44;a->h1+=c;
}

static PyObject*enc(PyObject*self,PyObject*args){
  Py_buffer K,N,P,A; int nthreads;
  if(!PyArg_ParseTuple(args,"y*y*y*y*i",&K,&N,&P,&A,&nthreads))return NULL;
  if(K.len!=32||N.len!=12){PyErr_SetString(PyExc_ValueError,"bad key/nonce");goto fail;}
  size_t len=P.len;
  PyObject*ctobj=PyBytes_FromStringAndSize(NULL,len);
  if(!ctobj)goto fail;
  uint8_t*ct=(uint8_t*)PyBytes_AS_STRING(ctobj);
  uint8_t tag[16]; int err=0;
  Py_BEGIN_ALLOW_THREADS
  {
    const uint8_t*key=K.buf,*nonce=N.buf;
    uint8_t iv[16]={0}; memcpy(iv+4,nonce,12);
    uint8_t blk[64]={0},z[64]={0}; int ol;
    EVP_CIPHER_CTX*c=EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(c,EVP_chacha20(),NULL,key,iv);
    EVP_EncryptUpdate(c,blk,&ol,z,64);
    EVP_CIPHER_CTX_free(c);
    pkey pk; pkey_init(&pk,blk);
    /* AAD */
    pacc h={0,0,0};
    size_t al=A.len,anb=al/16;
    pblocks(&h,&pk,A.buf,anb);
    if(al%16){uint8_t b[16]={0};memcpy(b,(uint8_t*)A.buf+anb*16,al%16);pblocks(&h,&pk,b,1);}
    size_t ctblocks=(len+15)/16;
    int nt=nthreads; if(nt<1)nt=1; if(nt>MAXT)nt=MAXT;
    if(len<(1<<20)) nt=1;
    job jobs[MAXT]; pthread_t th[MAXT];
    size_t per=(len/nt+63)&~(size_t)63;
    int used=0; size_t off=0;
    for(int i=0;i<nt&&off<len;i++){
      size_t l=per; if(off+l>len||i==nt-1)l=len-off;
      jobs[i].pt=P.buf;jobs[i].ct=ct;jobs[i].off=off;jobs[i].len=l;jobs[i].key=key;jobs[i].nonce=nonce;jobs[i].pk=pk;
      off+=l; used++;
    }
    for(int i=1;i<used;i++) pthread_create(&th[i],NULL,worker,&jobs[i]);
    if(used>0) worker(&jobs[0]);
    for(int i=1;i<used;i++) pthread_join(th[i],NULL);
    for(int i=0;i<used;i++) err|=jobs[i].err;
    /* combine: total = h*r^(ctblocks+1) + sum acc_i * r^(blocks after i +1) ; plus length block */
    pacc tot,t; pkey mk;
    ppow(&t,&pk,ctblocks); key_from_acc(&mk,&t); tot=h; pmul(&tot,&mk);
    size_t bdone=0;
    for(int i=0;i<used;i++){
      size_t nb=(jobs[i].len+15)/16; bdone+=nb;
      pacc a=jobs[i].acc;
      ppow(&t,&pk,ctblocks-bdone); key_from_acc(&mk,&t); pmul(&a,&mk);
      addacc(&tot,&a);
    }
    uint8_t lb[16]; uint64_t a64=al,c64=len; memcpy(lb,&a64,8);memcpy(lb+8,&c64,8);
    pblocks(&tot,&pk,lb,1);
    /* final reduce */
    uint64_t h0=tot.h0,h1=tot.h1,h2=tot.h2,cc;
    const uint64_t m44=0xfffffffffffULL,m42=0x3ffffffffffULL;
    cc=h1>>44;h1&=m44;h2+=cc; cc=h2>>42;h2&=m42;h0+=cc*5; cc=h0>>44;h0&=m44;h1+=cc;
    cc=h1>>44;h1&=m44;h2+=cc; cc=h2>>42;h2&=m42;h0+=cc*5; cc=h0>>44;h0&=m44;h1+=cc;
    uint64_t g0=h0+5; cc=g0>>44; g0&=m44;
    uint64_t g1=h1+cc; cc=g1>>44; g1&=m44;
    uint64_t g2=h2+cc-(1ULL<<42);
    cc=(g2>>63)-1; /* all ones if g2 didn't underflow */
    g0&=cc;g1&=cc;g2&=cc; cc=~cc;
    h0=(h0&cc)|g0; h1=(h1&cc)|g1; h2=(h2&cc)|g2;
    uint64_t s0=ld64(blk+16),s1=ld64(blk+24);
    uint64_t t0=s0,t1=s1;
    h0+=t0&m44; cc=h0>>44;h0&=m44;
    h1+=(((t0>>44)|(t1<<20))&m44)+cc; cc=h1>>44;h1&=m44;
    h2+=((t1>>24)&m42)+cc; h2&=m42;
    h0=(h0|(h1<<44)); h1=((h1>>20)|(h2<<24));
    memcpy(tag,&h0,8);memcpy(tag+8,&h1,8);
  }
  Py_END_ALLOW_THREADS
  PyBuffer_Release(&K);PyBuffer_Release(&N);PyBuffer_Release(&P);PyBuffer_Release(&A);
  if(err){Py_DECREF(ctobj);PyErr_SetString(PyExc_RuntimeError,"openssl");return NULL;}
  PyObject*tg=PyBytes_FromStringAndSize((char*)tag,16);
  return Py_BuildValue("NN",ctobj,tg);
fail:
  PyBuffer_Release(&K);PyBuffer_Release(&N);PyBuffer_Release(&P);PyBuffer_Release(&A);
  return NULL;
}
